const API = "http://localhost:5000";

async function apiFetch(endpoint) {
  try {
    const res = await fetch(API + endpoint);
    if (!res.ok) throw new Error("HTTP " + res.status);
    return await res.json();
  } catch (e) { return null; }
}

async function apiPost(endpoint, data) {
  try {
    const res = await fetch(API + endpoint, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data)
    });
    return await res.json();
  } catch (e) { showToast("Connection error", "error"); return null; }
}

async function apiPut(endpoint, data) {
  try {
    const res = await fetch(API + endpoint, {
      method: "PUT", headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data)
    });
    return await res.json();
  } catch (e) { showToast("Connection error", "error"); return null; }
}

async function apiDelete(endpoint) {
  try {
    const res = await fetch(API + endpoint, { method: "DELETE" });
    return await res.json();
  } catch (e) { showToast("Connection error", "error"); return null; }
}

function showToast(msg, type = "") {
  const t = document.getElementById("toast");
  t.textContent = msg; t.className = "toast show " + type;
  setTimeout(() => t.className = "toast", 3000);
}

function showModal(id) { document.getElementById(id).classList.add("open"); }
function closeModal(id) { document.getElementById(id).classList.remove("open"); }

document.addEventListener("click", e => {
  if (e.target.classList.contains("modal-overlay")) e.target.classList.remove("open");
});

function filterTable(tableId, query) {
  const rows = document.querySelectorAll("#" + tableId + " tbody tr");
  const q = query.toLowerCase();
  rows.forEach(row => { row.style.display = row.textContent.toLowerCase().includes(q) ? "" : "none"; });
}

function badge(status) {
  const s = (status || "").toLowerCase().replace(" ", "-");
  const map = { delivered:"badge-delivered", pending:"badge-pending", shipped:"badge-shipped",
                open:"badge-open", "in-progress":"badge-in-progress", closed:"badge-closed" };
  return `<span class="badge ${map[s]||""}">${status||"—"}</span>`;
}

function stars(n) {
  n = Number(n) || 0;
  return `<span class="stars">${"★".repeat(n)}${"☆".repeat(5-n)}</span>`;
}

function trunc(str, n) {
  if (!str) return "—";
  return str.length > n ? str.substring(0, n) + "…" : str;
}

function formatDate(d) {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-US", { year:"numeric", month:"short", day:"numeric" });
}

function formatTimestamp(ts) {
  if (!ts) return "—";
  return new Date(ts).toLocaleString("en-US", { month:"short", day:"numeric", hour:"2-digit", minute:"2-digit" });
}

function logout() {
  sessionStorage.removeItem("user");
  window.location.href = "login.html";
}